-- USKOČI worker regions + unlimited (200) work areas — candidate 2026-11-22.
-- Owner decision 22.11.2026: a worker may name any number of cities, a region
-- ("cela Vojvodina", "Srem", "Banat", a district) or all of Serbia. A REGION area
-- matches a task when the task point lies in one of the region's districts.
-- District boundaries: © OpenStreetMap contributors (ODbL), admin_level 6
-- (upravni okruzi + Grad Beograd), simplified to ~100 m, verified on 31 towns.
BEGIN;

DO $guard$
BEGIN
  IF md5((SELECT prosrc FROM pg_proc WHERE oid='private.validate_worker_areas_v1(jsonb)'::regprocedure))<>'8f1cd592eb48eb9da31e0af02c0bdd2e'
  OR md5((SELECT prosrc FROM pg_proc WHERE oid='private.worker_area_fit_v1(jsonb,text,text,text,numeric,numeric)'::regprocedure))<>'859d6f0a9ab940793b7cdab7ddbab2cd'
  OR to_regclass('private.rs_district_boundary') IS NOT NULL
  THEN RAISE EXCEPTION 'WORKER_REGIONS_PREIMAGE_MISMATCH'; END IF;
END $guard$;

CREATE TABLE private.rs_district_boundary (
  code text PRIMARY KEY CHECK (code ~ '^RS-(0[0-9]|1[0-9]|2[0-4])$'),
  name text NOT NULL CHECK (length(name) BETWEEN 2 AND 80),
  geom extensions.geometry(MultiPolygon,4326) NOT NULL
);
ALTER TABLE private.rs_district_boundary ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON private.rs_district_boundary FROM PUBLIC, anon, authenticated;
CREATE INDEX rs_district_boundary_geom_gist ON private.rs_district_boundary USING gist (geom);

