-- Region code -> its districts. Geographic names map to whole districts.
CREATE FUNCTION private.worker_region_districts_v1(code text)
 RETURNS text[] LANGUAGE sql IMMUTABLE SET search_path TO 'pg_catalog' AS $f$
 select case code
  when 'RS-VO' then array['RS-01','RS-02','RS-03','RS-04','RS-05','RS-06','RS-07']
  when 'RS-BG' then array['RS-00']
  when 'RS-SZ' then array['RS-08','RS-09','RS-12','RS-13','RS-16','RS-17','RS-18','RS-19']
  when 'RS-JI' then array['RS-10','RS-11','RS-14','RS-15','RS-20','RS-21','RS-22','RS-23','RS-24']
  when 'RS-BACKA' then array['RS-01','RS-05','RS-06']
  when 'RS-BANAT' then array['RS-02','RS-03','RS-04']
  when 'RS-SREM' then array['RS-07']
  else case when code ~ '^RS-(0[1-9]|1[0-9]|2[0-4])$' then array[code] end
 end;
$f$;

CREATE FUNCTION private.worker_region_label_v1(code text)
 RETURNS text LANGUAGE sql IMMUTABLE SET search_path TO 'pg_catalog' AS $f$
 select case code
  when 'RS-VO' then 'Cela Vojvodina' when 'RS-BG' then 'Ceo Beograd'
  when 'RS-SZ' then 'Šumadija i Zapadna Srbija' when 'RS-JI' then 'Južna i Istočna Srbija'
  when 'RS-BACKA' then 'Bačka' when 'RS-BANAT' then 'Banat' when 'RS-SREM' then 'Srem'
  when 'RS-01' then 'Severnobački okrug' when 'RS-02' then 'Srednjobanatski okrug' when 'RS-03' then 'Severnobanatski okrug'
  when 'RS-04' then 'Južnobanatski okrug' when 'RS-05' then 'Zapadnobački okrug' when 'RS-06' then 'Južnobački okrug'
  when 'RS-07' then 'Sremski okrug' when 'RS-08' then 'Mačvanski okrug' when 'RS-09' then 'Kolubarski okrug'
  when 'RS-10' then 'Podunavski okrug' when 'RS-11' then 'Braničevski okrug' when 'RS-12' then 'Šumadijski okrug'
  when 'RS-13' then 'Pomoravski okrug' when 'RS-14' then 'Borski okrug' when 'RS-15' then 'Zaječarski okrug'
  when 'RS-16' then 'Zlatiborski okrug' when 'RS-17' then 'Moravički okrug' when 'RS-18' then 'Raški okrug'
  when 'RS-19' then 'Rasinski okrug' when 'RS-20' then 'Nišavski okrug' when 'RS-21' then 'Toplički okrug'
  when 'RS-22' then 'Pirotski okrug' when 'RS-23' then 'Jablanički okrug' when 'RS-24' then 'Pčinjski okrug'
 end;
$f$;

-- The district that contains a task point (approximate public point is enough).
CREATE FUNCTION private.rs_district_at_v1(lat numeric, lng numeric)
 RETURNS text LANGUAGE sql STABLE SET search_path TO 'pg_catalog' AS $f$
 select b.code from private.rs_district_boundary b
 where lat is not null and lng is not null
   and extensions.st_covers(b.geom, extensions.st_setsrid(extensions.st_makepoint(lng::float8, lat::float8), 4326))
 order by b.code limit 1;
$f$;

CREATE OR REPLACE FUNCTION private.validate_worker_areas_v1(areas jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$
declare a jsonb; seen text[]:='{}'; key text;
begin
 if jsonb_typeof(areas) is distinct from 'array' or jsonb_array_length(areas)>200 then raise exception 'WORKER_AREA_INVALID' using errcode='22023'; end if;
 for a in select value from jsonb_array_elements(areas) loop
  if jsonb_typeof(a)<>'object' or a-array['kind','countryCode','label','city','sourceRef','latitude','longitude','radiusKm']<>'{}'
   or not a?&array['kind','countryCode','label','city','sourceRef','latitude','longitude','radiusKm']
   or jsonb_typeof(a->'kind')<>'string' or a->>'kind' not in ('COUNTRY','REGION','CITY','RADIUS') or a->>'countryCode' is distinct from 'RS'
   or jsonb_typeof(a->'label')<>'string' or length(a->>'label') not between 2 and 200 or a->>'label'~'[[:cntrl:]]'
  then raise exception 'WORKER_AREA_INVALID' using errcode='22023'; end if;
  if a->>'kind'='COUNTRY' then
   if jsonb_array_length(areas)<>1 or a->>'label'<>'Cela Srbija'
    or a->'city'<>'null' or a->'sourceRef'<>'null' or a->'latitude'<>'null' or a->'longitude'<>'null' or a->'radiusKm'<>'null'
   then raise exception 'WORKER_AREA_INVALID' using errcode='22023'; end if;
   key:='RS';
  elsif a->>'kind'='REGION' then
   if a->'city'<>'null' or a->'latitude'<>'null' or a->'longitude'<>'null' or a->'radiusKm'<>'null'
    or jsonb_typeof(a->'sourceRef')<>'string' or a->>'sourceRef'!~'^region:RS-[A-Z0-9]{2,5}$'
    or private.worker_region_districts_v1(substr(a->>'sourceRef',8)) is null
    or a->>'label' is distinct from private.worker_region_label_v1(substr(a->>'sourceRef',8))
   then raise exception 'WORKER_AREA_INVALID' using errcode='22023'; end if;
   key:=a->>'sourceRef';
  else
   if jsonb_typeof(a->'city')<>'string' or length(a->>'city') not between 2 and 160 or a->>'city'~'[[:cntrl:]]'
    or jsonb_typeof(a->'sourceRef')<>'string' or a->>'sourceRef'!~'^osm:(node|way|relation):[1-9][0-9]{0,19}$'
    or jsonb_typeof(a->'latitude')<>'number' or jsonb_typeof(a->'longitude')<>'number'
   then raise exception 'WORKER_AREA_INVALID' using errcode='22023'; end if;
   if (a->>'latitude')::numeric not between -90 and 90 or (a->>'longitude')::numeric not between -180 and 180
    or round((a->>'latitude')::numeric,2)<>(a->>'latitude')::numeric or round((a->>'longitude')::numeric,2)<>(a->>'longitude')::numeric
   then raise exception 'WORKER_AREA_INVALID' using errcode='22023'; end if;
   if a->>'kind'='CITY' then
    if a->'radiusKm'<>'null' or a->>'label'<>a->>'city' then raise exception 'WORKER_AREA_INVALID' using errcode='22023'; end if;
   else
    if jsonb_typeof(a->'radiusKm')<>'number' or a->>'radiusKm'!~'^([1-9]|[1-9][0-9]|1[0-9][0-9]|200)$'
      or a->>'label'<>((a->>'city')||' · do '||(a->>'radiusKm')||' km') then raise exception 'WORKER_AREA_INVALID' using errcode='22023'; end if;
   end if;
   key:=a->>'sourceRef';
  end if;
  if key=any(seen) then raise exception 'WORKER_AREA_INVALID' using errcode='22023'; end if;
  seen:=array_append(seen,key);
 end loop;
 return areas;
end $function$;

CREATE OR REPLACE FUNCTION private.worker_area_fit_v1(areas jsonb, mode text, country text, city text, lat numeric, lng numeric)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog'
AS $function$
declare a jsonb; district text; district_known boolean:=false;
begin
 if jsonb_array_length(areas)=0 or mode='REMOTE' then return null; end if;
 if mode not in ('STATIONARY','POINT_TO_POINT','MULTI_STOP','AREA_BASED') or country is distinct from 'RS' then return false; end if;
 for a in select value from jsonb_array_elements(areas) loop
  if a->>'kind'='COUNTRY' then return true; end if;
  if a->>'kind'='CITY' and private.worker_area_city_key_v1(city)<>''
   and private.worker_area_city_key_v1(city)=private.worker_area_city_key_v1(a->>'city') then return true; end if;
  if a->>'kind'='RADIUS' and lat is not null and lng is not null
   and private.haversine_km(lat,lng,(a->>'latitude')::numeric,(a->>'longitude')::numeric)<=(a->>'radiusKm')::numeric then return true; end if;
  if a->>'kind'='REGION' and lat is not null and lng is not null then
   if not district_known then district:=private.rs_district_at_v1(lat,lng); district_known:=true; end if;
   if district is not null and district=any(private.worker_region_districts_v1(substr(a->>'sourceRef',8))) then return true; end if;
  end if;
 end loop;
 return false;
end $function$;

DO $post$
DECLARE r jsonb;
BEGIN
  IF (SELECT count(*) FROM private.rs_district_boundary)<>25
  OR EXISTS (SELECT 1 FROM private.rs_district_boundary WHERE NOT extensions.st_isvalid(geom))
  OR private.rs_district_at_v1(45.27,19.83) IS DISTINCT FROM 'RS-06'
  OR private.rs_district_at_v1(44.84,20.40) IS DISTINCT FROM 'RS-00'
  OR private.rs_district_at_v1(44.98,19.90) IS DISTINCT FROM 'RS-07'
  OR private.rs_district_at_v1(43.32,21.90) IS DISTINCT FROM 'RS-20'
  OR private.rs_district_at_v1(48.21,16.37) IS NOT NULL
  THEN RAISE EXCEPTION 'WORKER_REGIONS_POSTIMAGE_DISTRICTS'; END IF;
  r:='[{"kind":"REGION","countryCode":"RS","label":"Cela Vojvodina","city":null,"sourceRef":"region:RS-VO","latitude":null,"longitude":null,"radiusKm":null}]';
  IF private.validate_worker_areas_v1(r)<>r
  OR private.worker_area_fit_v1(r,'STATIONARY','RS','Tometino Polje',44.98,19.90) IS NOT TRUE
  OR private.worker_area_fit_v1(r,'STATIONARY','RS','Zemun',44.84,20.40) IS NOT FALSE
  OR private.worker_area_fit_v1(r,'REMOTE','RS',null,null,null) IS NOT NULL
  THEN RAISE EXCEPTION 'WORKER_REGIONS_POSTIMAGE_FIT'; END IF;
  BEGIN
    PERFORM private.validate_worker_areas_v1('[{"kind":"REGION","countryCode":"RS","label":"Vojvodina","city":null,"sourceRef":"region:RS-VO","latitude":null,"longitude":null,"radiusKm":null}]');
    RAISE EXCEPTION 'WORKER_REGIONS_POSTIMAGE_LABEL';
  EXCEPTION WHEN sqlstate '22023' THEN NULL; END;
END $post$;

COMMIT;
